INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'zhTW', '命定誘惑：首創者聖塚', '', '', '', '', '', '', '', '', 45114),
(66694, 'zhTW', '命定誘惑：統御聖所', '', '', '', '', '', '', '', '', 45114),
(66661, 'zhTW', '只是個不值錢的硬幣', '到奧睿博司尋找仲介者以獲得更多訊息。', '<你對這個奇怪的物品有很多疑惑。你是怎麼取得它的？它有什麼用途？它有危險性嗎？>\n\n<如果永恆之城沒有你要的答案，那麼在那裡行商的仲介者一定能替你解惑。>', '', '', '', '', '', '', 45114),
(66649, 'zhTW', '轉動命運', '擊敗$1oa個不同的命定團隊副本首領。', '<經過多次試煉，有股力量在你體內滋長。這些不明的異象，如今已不會使你困惑，反而讓你感到自在。>\n\n<再次奔向未知。與黑暗搏鬥，緊握自己的命運。>', '', '', '', '', '', '', 45114),
(66648, 'zhTW', '命運交織', '擊敗30個不同的命定團隊副本首領。', '<現實圍繞，你對這個地方的記憶，隨著時間的流逝變得模糊、扭曲。某個東西改變了。>\n\n<儘管似曾相識，但你非常確定這不是你所熟悉的那個地方。不完全一樣。>\n\n<然而，前方的道路等著。你不會讓詭計或扭曲的現實耽誤你的宿命。>', '', '', '', '', '', '', 45114),
(66619, 'zhTW', '安托斯', '', '', '', '', '', '', '', '', 45114),
(66618, 'zhTW', '莫傑斯', '', '', '', '', '', '', '', '', 45114),
(66615, 'zhTW', '『淤泥化身』納苟許', '', '', '', '', '', '', '', '', 45114),
(65412, 'zhTW', '解開謎題', '', '', '', '', '', '', '', '', 45114),
(65135, 'zhTW', '朋友的朋友：艾利歐德樹林長', '', '', '', '', '', '', '', '', 45114),
(65096, 'zhTW', '不是你死，就是我亡', '殺死懲戒者馬卡瑞斯並收集$2oa個聖物。', '我們從悠恆裂片找到的物品獲得了大量的資訊。\n\n但是淵誓者發現了這件事，並且企圖妨礙我們。他們在區域周圍放置了陷阱，阻礙我們取得文物。\n\n閻獄之主不希望我們獲得其中的知識，我們絕不能讓他得逞。\n\n請消滅淵誓者，並盡可能地多帶一點聖物回來。', '', '托迦司許多陷阱的製作者。來到澤瑞斯莫提斯開始設置陷阱。', '懲戒者馬卡瑞斯', '', '', '', 45114),
(64977, 'zhTW', '進入鬥技場', '擊敗映現樞核所產生的造物。', '這片土地有著許多奇妙的特性，比方說這裡雖然歷史悠久，但仍然能夠適應周遭的變化並隨之改變。這裡的事物並不是靜止不變的。\n\n在映現樞核的內部深處，有個熔爐似乎是專門用來測試各種造物並從中學習的熔爐。這些生物說不定有朝一日會被用來抵禦澤瑞斯莫提斯的外敵，因此你應該盡可能把握機會測試它們的性能。\n\n過去那裡挑戰熔爐的造物，然後回來跟我回報吧。', '', '', '', '', '', '', 45114),
(64579, 'zhTW', '空爐微粒回收', '使用法琳的熔爐分流器從創先者熔爐收集$1oa個殘餘新微粒。', '散落在澤瑞斯莫提斯各處的大型金屬球體是已經退役的熔爐，在造物過程中遭到廢棄。\n\n這些金屬空殼裡面還殘留著造物材料，說不定會對我們有所幫助。\n\n在這些金屬球體附近使用熔爐分流器，採集其中的殘餘新微粒。你說不定還能同時找到其他實用的原靈體材料！', '', '', '', '', '', '', 45114),
(56904, 'zhTW', '豐饒之冠', '從安戈洛環形山、荊棘谷和北貧瘠之地收集花朵。', '你的花冠真是五彩繽紛！如此美妙的粉紅、黃、藍搭配…要是能保存下來就好了。\n\n雖然這些花朵無法永存，但我知道有別的花可以！\n\n在每年的新年慶典都會綻放類似的花朵。因為你的所作所為，讓我瞭解它們與伊露恩之間有一股我能進一步加強的連繫。幫我取得花朵，我們就可以編成花冠，讓你享用一整年！', '', '', '', '', '', '回到月光林地去找麥蕊兒‧月綻。', 45114),
(54688, 'zhTW', '審判官艾瑞克', '', '', '', '', '', '', '', '', 45114),
(53317, 'zhTW', '緻密的風暴白銀', '', '', '', '', '', '', '', '', 45114),
(44191, 'zhTW', '危險：卡薩克斯', '', '', '', '', '', '', '', '', 45114),
(43619, 'zhTW', '懸賞：夏菈‧魔息', '', '', '', '', '', '', '', '', 45114),
(34530, 'zhTW', 'Shaper Dungeon [PH] Challenge Mode - Consolation (Nth)', '', '', '', '', '', '', '', '', 45114),
(32427, 'zhTW', '領袖的氣度', '與霧隱客棧的怒西昂交談。', '我們針對熊貓人的計畫已經進展到了下個階段。你的大酋長希望能展現部落的強大軍力，讓熊貓人留下深刻的印象。不論有沒有獲得熊貓人的支持，他都打定主意要奪走這塊大陸的資源。$b$b我雖然瞭解你們領導人的目標，但是我更希望能瞭解他本人。他的動機是什麼?部落最後要走向哪裡?我想跟你聊聊你們的這位領導人。', '', '', '', '', '', '', 45114),
(31518, 'zhTW', '恆春谷', '到聖獸天尊之門找安杜因。', '距離上次山谷大門打開，已經是許多許多世代之前的事了，$n。$b$b我絕對不會錯過這件事，而你也不該錯過它!$b$b到崑萊峰的南方邊界跟我碰頭。我會在那裡等你。', '', '', '', '', '', '', 45114),
(343, 'zhTW', '關於堅韌的演講', '到暴風要塞的皇家圖書館去與密爾頓·西弗交談，他將會為你找到克里斯多夫修士所需要的關於冶金學的書。', '我正要作一次關於「堅韌的靈魂」的演講，我想引用一本關於金屬學的著作《金屬的延展性》裡的一些段落。暴風要塞裡的皇家圖書館裡應該有這本書的副本。你能把它拿來給我嗎?如果可以的話，聖光定會保佑你的!$B$B皇家圖書館很大，但首席管理員密爾頓·西弗對每一個書架上有些什麼書都瞭若指掌。告訴他我需要什麼，他就會把書找給你的。', '', '', '', '', '', '', 45114);

